-- Every record below is synthetic. Auth roles exercise the actual new function ACLs.
CREATE FUNCTION public.room_assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
